import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';

// Checks on generated bytes only; no browser or payload is executed.
export function inspectStaticHtml(html) {
  assert.equal(typeof html, 'string');
  assert.match(html, /<!doctype html>/i);
  assert.match(html, /<html\b[^>]*lang="pt-BR"/i);
  assert.match(html, /<main\b/i);
  assert.doesNotMatch(html, /<(?:iframe|object|embed)\b/i);
  assert.doesNotMatch(html, /\son[a-z]+\s*=/i);
  assert.doesNotMatch(html, /\s(?:src|href|action)\s*=\s*["'](?:https?:|\/\/|javascript:)/i);
  assert.doesNotMatch(html, /(?:x|y|width|height|cx|cy|d|points)="[^"]*(?:NaN|Infinity)/);
  const markup = html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
  const ids = Array.from(markup.matchAll(/\bid="([^"]+)"/g), m => m[1]);
  assert.equal(ids.length, new Set(ids).size, 'HTML/SVG ids must be unique');
  const idSet = new Set(ids);
  for (const m of markup.matchAll(/\b(?:aria-labelledby|aria-describedby)="([^"]+)"/g)) {
    for (const id of m[1].split(/\s+/)) assert.ok(idSet.has(id), `missing aria target ${id}`);
  }
  for (const m of markup.matchAll(/\bhref="#([^"]+)"/g)) assert.ok(idSet.has(m[1]), `missing fragment target ${m[1]}`);
  const policy = html.match(/<meta\s+[^>]*http-equiv="Content-Security-Policy"[^>]*content="([^"]+)"[^>]*>/i)?.[1];
  assert.ok(policy, 'CSP meta is required');
  assert.match(policy, /default-src 'none'/);
  assert.match(policy, /connect-src 'none'/);
  assert.match(policy, /form-action 'none'/);
  assert.match(policy, /base-uri 'none'/);
  assert.match(policy, /object-src 'none'/);
  const blocks = Array.from(html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi));
  for (const [,attributes,bytes] of blocks) {
    assert.doesNotMatch(attributes, /\bsrc\s*=/i);
    assert.ok(policy.includes(`'sha256-${createHash('sha256').update(bytes).digest('base64')}'`), 'script CSP must cover actual bytes');
  }
  assert.doesNotMatch(policy.match(/(?:^|;)\s*script-src\s+([^;]+)/)?.[1] ?? '', /unsafe-inline|unsafe-eval/);
  for (const [, bytes] of html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)) {
    assert.ok(policy.includes(`'sha256-${createHash('sha256').update(bytes).digest('base64')}'`), 'style CSP must cover actual bytes');
  }
  assert.doesNotMatch(markup, /\sstyle\s*=/i);
  assert.match(html, /prefers-reduced-motion/);
  return { ids: ids.length, scriptBlocks: blocks.length };
}

export function deepFreeze(value) {
  if (value && typeof value === 'object') {
    Object.freeze(value);
    for (const item of Object.values(value)) deepFreeze(item);
  }
  return value;
}
